import re
from dataclasses import dataclass, field
from typing import Optional

HEADING = re.compile(r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$")
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)
_MARK = "\x00"


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    """Remove HTML comments, dropping whitespace they leave at line ends."""
    text = text.replace(_MARK, "")
    text = COMMENT.sub(_MARK, text)
    text = re.sub(rf"(?:[ \t]*{_MARK})+[ \t]*$", "", text, flags=re.MULTILINE)
    return text.replace(_MARK, "")


def parse_changelog(text):
    releases = []
    current = None
    for line in strip_comments(text).splitlines():
        match = HEADING.match(line) if line.startswith("## ") else None
        if match:
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _clean_body(lines):
    out = []
    for line in lines:
        if not line.strip():
            if out and out[-1] == "":
                continue
            line = ""
        out.append(line)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            title = f"{release.version} ({release.date})" if release.date else release.version
            if not release.date:
                title = release.version
            body = _clean_body(release.body)
            return f"# {title}\n\n{body}\n"
    raise LookupError(version)
EOF
